/*
 * prog50_binary_heap.c
 *
 * Re‑implementation of the original binary‑heap program.
 *
 * Behaviour (as observed from the de‑compiled binary):
 *
 *   • If the program is started without any command‑line arguments
 *     it prints the single line
 *
 *           NOOP
 *
 *   • Otherwise each argument is processed in order.
 *
 *   •  I<number>   – insert the signed decimal integer <number> into a
 *                    min‑heap (capacity 15).  On success prints
 *
 *                        INS %ld\n          (the inserted value)
 *
 *                    If the heap is already full prints
 *
 *                        FULL
 *
 *                    If the part after the leading ‘I’ is not a valid
 *                    integer prints
 *
 *                        ERR
 *
 *   •  X           – extract the minimum element from the heap.
 *                    If the heap is empty prints
 *
 *                        EMPTY
 *
 *                    otherwise prints
 *
 *                        MIN %ld\n          (the extracted value)
 *
 *   •  any other argument prints
 *
 *                        ERR
 *
 * The heap is a classic binary min‑heap stored in a static array of
 * long values.  The implementation follows the usual sift‑up / sift‑down
 * algorithms and matches the limits observed in the original binary
 * (maximum 15 elements).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define HEAP_CAP 15          /* maximum number of elements */

static long heap[HEAP_CAP];
static int  size = 0;        /* current number of elements */

/* --------------------------------------------------------------- */
/* Helper: swap two elements in the heap array                      */
static void swap(int i, int j)
{
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

/* --------------------------------------------------------------- */
/* Insert a value into the min‑heap.  Returns 0 on success,
 * 1 if the heap is already full.                                   */
static int heap_insert(long v)
{
    if (size >= HEAP_CAP)
        return 1;                     /* FULL */

    int i = size;
    heap[i] = v;
    ++size;

    /* sift‑up */
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] <= heap[i])
            break;
        swap(parent, i);
        i = parent;
    }
    return 0;
}

/* --------------------------------------------------------------- */
/* Extract the minimum element.  Returns 0 on success,
 * 1 if the heap is empty.  The extracted value is stored in *out.   */
static int heap_extract_min(long *out)
{
    if (size == 0)
        return 1;                     /* EMPTY */

    *out = heap[0];
    heap[0] = heap[size - 1];
    --size;

    /* sift‑down */
    int i = 0;
    while (1) {
        int left  = 2 * i + 1;
        int right = 2 * i + 2;
        int smallest = i;

        if (left  < size && heap[left]  < heap[smallest])
            smallest = left;
        if (right < size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest == i)
            break;

        swap(i, smallest);
        i = smallest;
    }
    return 0;
}

/* --------------------------------------------------------------- */
int main(int argc, char **argv)
{
    /* No arguments (apart from program name) → NOOP */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int idx = 1; idx < argc; ++idx) {
        const char *arg = argv[idx];

        if (arg[0] == 'I' && arg[1] != '\0') {
            /* Insert command – parse the number after the leading 'I' */
            char *endptr;
            errno = 0;
            long val = strtol(arg + 1, &endptr, 10);

            if (endptr == arg + 1 || *endptr != '\0' || errno != 0) {
                puts("ERR");
                continue;
            }

            if (heap_insert(val) == 1) {
                puts("FULL");
            } else {
                printf("INS %ld\n", val);
            }
        }
        else if (strcmp(arg, "X") == 0) {
            long minval;
            if (heap_extract_min(&minval) == 1) {
                puts("EMPTY");
            } else {
                printf("MIN %ld\n", minval);
            }
        }
        else {
            /* Anything else is an error */
            puts("ERR");
        }
    }

    return 0;
}
